import type { List, Status, Task, StatusCategory } from '../index'

interface FetchOptions {
  method?: string
  body?: unknown
  query?: Record<string, string | undefined>
}

type Fetcher = <T>(url: string, options?: FetchOptions) => Promise<T>

export function createApiClient(fetcher: Fetcher) {
  return {
    lists: {
      getAll: () =>
        fetcher<List[]>('/api/v1/lists'),

      create: (body: { name: string; is_inbox?: boolean; sort_order?: number }) =>
        fetcher<List>('/api/v1/lists', { method: 'POST', body }),

      update: (id: string, body: { name?: string; sort_order?: number; is_inbox?: boolean }) =>
        fetcher<List>(`/api/v1/lists/${id}`, { method: 'PATCH', body }),

      delete: (id: string) =>
        fetcher<null>(`/api/v1/lists/${id}`, { method: 'DELETE' }),
    },

    statuses: {
      getAll: (query?: { list_id?: string }) =>
        fetcher<Status[]>('/api/v1/statuses', { query }),

      create: (body: {
        name: string
        category?: StatusCategory
        color?: string
        sort_order?: number
        list_id?: string | null
      }) =>
        fetcher<Status>('/api/v1/statuses', { method: 'POST', body }),

      update: (id: string, body: {
        name?: string
        category?: StatusCategory
        color?: string
        sort_order?: number
        list_id?: string | null
      }) =>
        fetcher<Status>(`/api/v1/statuses/${id}`, { method: 'PATCH', body }),

      delete: (id: string) =>
        fetcher<null>(`/api/v1/statuses/${id}`, { method: 'DELETE' }),
    },

    tasks: {
      getAll: (query?: { list_id?: string; scheduled_date?: string; status_id?: string }) =>
        fetcher<Task[]>('/api/v1/tasks', { query }),

      get: (id: string) =>
        fetcher<Task>(`/api/v1/tasks/${id}`),

      create: (body: {
        title: string
        list_id?: string
        status_id?: string
        scheduled_date?: string | null
      }) =>
        fetcher<Task>('/api/v1/tasks', { method: 'POST', body }),

      update: (id: string, body: {
        title?: string
        status_id?: string
        list_id?: string
        scheduled_date?: string | null
        sort_order?: number
        deleted_at?: string | null
      }) =>
        fetcher<Task>(`/api/v1/tasks/${id}`, { method: 'PATCH', body }),
    },

    setup: {
      init: (body: {
        lists?: Array<{ name: string; is_inbox: boolean }>
        statuses?: Array<{ name: string; category: StatusCategory; color: string }>
      }) =>
        fetcher<unknown>('/api/v1/setup/init', { method: 'POST', body }),
    },
  }
}

export type ApiClient = ReturnType<typeof createApiClient>

import type { List, Status, Task } from '@nusk/shared'

const toDateStr = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`

export const useTaskStore = () => {
  const api = useApi()

  const lists = useState<List[]>('task-lists', () => [])
  const statuses = useState<Status[]>('task-statuses', () => [])
  const tasks = useState<Task[]>('task-items', () => [])

  const loading = useState('task-loading', () => false)
  const loaded = useState('task-loaded', () => false)

  const selectedListId = useState<string>('selected-list-id', () => '')
  const viewMode = useState<'list' | 'date'>('view-mode', () => 'list')

  const selectedList = computed(() =>
    lists.value.find(l => l.id === selectedListId.value),
  )

  const filteredTasks = computed(() =>
    tasks.value.filter(t => t.list_id === selectedListId.value),
  )

  const getStatus = (statusId: string) =>
    statuses.value.find(s => s.id === statusId)

  const taskCount = (listId: string) =>
    tasks.value.filter(t => t.list_id === listId).length

  const todayStr = computed(() => toDateStr(new Date()))

  const tomorrowStr = computed(() => {
    const d = new Date()
    d.setDate(d.getDate() + 1)
    return toDateStr(d)
  })

  const todayCount = computed(() =>
    tasks.value.filter(t => t.scheduled_date === todayStr.value).length,
  )

  const tomorrowCount = computed(() =>
    tasks.value.filter(t => t.scheduled_date === tomorrowStr.value).length,
  )

  const isToday = (date: string | null) => date === todayStr.value

  const formatDate = (date: string | null) => {
    if (!date) return ''
    const d = new Date(date + 'T00:00:00')
    return `${d.getMonth() + 1}/${d.getDate()}`
  }

  async function fetchData() {
    if (loaded.value) return
    loading.value = true
    try {
      const [listsRes, statusesRes, tasksRes] = await Promise.all([
        api.lists.getAll(),
        api.statuses.getAll(),
        api.tasks.getAll(),
      ])
      lists.value = listsRes
      statuses.value = statusesRes
      tasks.value = tasksRes

      const inbox = lists.value.find(l => l.is_inbox)
      if (inbox && !selectedListId.value) {
        selectedListId.value = inbox.id
      }
      loaded.value = true
    } finally {
      loading.value = false
    }
  }

  async function addTask(title: string) {
    const task = await api.tasks.create({
      title,
      list_id: selectedListId.value,
    })
    tasks.value.push(task)
  }

  async function scheduleTask(taskId: string, date: string) {
    const updated = await api.tasks.update(taskId, { scheduled_date: date })
    const index = tasks.value.findIndex(t => t.id === taskId)
    if (index !== -1) tasks.value[index] = updated
  }

  async function completeTask(taskId: string) {
    const task = tasks.value.find(t => t.id === taskId)
    if (!task) return

    const currentStatus = statuses.value.find(s => s.id === task.status_id)
    const targetCategory = currentStatus?.category === 'DONE' ? 'TODO' : 'DONE'
    const newStatus = statuses.value.find(
      s => (s.list_id === task.list_id || s.list_id === null) && s.category === targetCategory,
    )
    if (!newStatus) return

    const updated = await api.tasks.update(taskId, { status_id: newStatus.id })
    const index = tasks.value.findIndex(t => t.id === taskId)
    if (index !== -1) tasks.value[index] = updated
  }

  return {
    lists,
    statuses,
    tasks,
    loading,
    loaded,
    selectedListId,
    viewMode,
    selectedList,
    filteredTasks,
    getStatus,
    taskCount,
    todayStr,
    tomorrowStr,
    todayCount,
    tomorrowCount,
    isToday,
    formatDate,
    fetchData,
    addTask,
    scheduleTask,
    completeTask,
  }
}

